import sys
sys.stdout.reconfigure(encoding='utf-8')
cap=821.58*459674889/1e6; sh=459.674889
OE={2007:(3617,4259),2008:(955,2212),2009:(797,764),2010:(3655,3821),2011:(5133,6210),2012:(518,2258),2013:(6126,6829),2014:(5575,5328),2015:(3262,3065),2016:(2461,1849),2017:(4337,3560),2018:(4929,4586),2019:(3592,3277),2020:(2858,2533),2021:(5848,5729),2022:(4867,5010),2023:(9817,10337),2024:(9226,10022),2025:(9242,10708)}
DS={2007:659.5,2008:627.9,2009:626.0,2010:650.4,2011:666.1,2012:669.6,2013:658.6,2014:628.9,2015:601.3,2016:584.3,2017:599.3,2018:599.4,2019:567.5,2020:548.6,2021:548.5,2022:530.4,2023:513.6,2024:489.4,2025:472.3}
def ps(ys,i): return sum(OE[y][i] for y in ys)/len(ys)/(sum(DS[y] for y in ys)/len(ys))
for a,b,n in [((2007,2008,2009,2010,2011),(2021,2022,2023,2024,2025),14),((2011,2012,2013,2014,2015),(2021,2022,2023,2024,2025),10),((2016,2017,2018,2019,2020),(2021,2022,2023,2024,2025),5)]:
    for i,lab in [(0,'capex end'),(1,'dep end')]:
        x,y=ps(a,i),ps(b,i); print(f'OE/share {a[0]}-{a[-1]} ${x:.2f} -> {b[0]}-{b[-1]} ${y:.2f} ({lab}): {((y/x)**(1/n)-1)*100:.1f}% a year over {n}y')
sg=((63980/41962)**(1/18)-1)*100; print(f'MP&E sales 2007-2025: {sg:.1f}% a year')
print(f'MP&E sales 2016-2025: {((63980/35773)**(1/9)-1)*100:.1f}% a year (trough start)')
cases=[('bottom boundary: 5y capex end + sales growth',7800,sg/100),('judged about $7bn + 5% ceiling',7000,0.05),('5y capex end ex customer advances + 5%',7164,0.05),('3y dep end + 5% ceiling',10356,0.05),('TTM dep end + 5% ceiling (most generous)',13746,0.05)]
for lab,oe,g in cases:
    y=oe/cap; v=oe/(0.10-g)
    print(f'{lab}: yield {y*100:.2f}% + g {g*100:.1f}% = expectancy {(y+g)*100:.1f}%; value at the 10% floor ${v/1e3:,.1f}bn = ${v/sh:,.0f} a share; growth needed at the price {(0.10-y)*100:.1f}%')
print('cap',round(cap,1))
